/*
 * A043576  Numbers whose base-2 representation has exactly 9 runs.
 * https://oeis.org/A043576
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 38, u32 n <= 38, u64 n <= 38, u128 n <= 38,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A043576: numbers whose binary representation has exactly 9 runs */
/* The sequence is generated by scanning the integers in increasing order
   and collecting those with exactly nine runs of consecutive identical bits.
   Numbers are sorted by numeric value as required. */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* Count runs of equal bits in the binary representation of a positive integer.
   For 0 the function returns 0. */
static size_t count_runs(idx_t x)
{
    if (x == 0) return 0;
    size_t runs = 1;
    uint8_t prev = (uint8_t)(x & 1);
    x >>= 1;
    while (x) {
        uint8_t bit = (uint8_t)(x & 1);
        if (bit != prev) ++runs;
        prev = bit;
        x >>= 1;
    }
    return runs;
}

/* Return the nth term (1‑based index) of sequence A043576. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* undefined for offset < 1 */

    /* Static cache to store already generated terms. */
    static seq_t *cache = NULL;
    static size_t cache_size = 0;
    static size_t cache_cap = 0;

    /* Keep scanning integers until the cache contains n terms. */
    static idx_t next = 1;                 /* next candidate to test */
    while (cache_size < (size_t)n) {
        /* Find the next integer with exactly 9 runs. */
        while (count_runs(next) != 9) ++next;

        /* Grow the cache if necessary. */
        if (cache_size == cache_cap) {
            cache_cap = (cache_cap ? (cache_cap << 1) : 8);
            cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
        }
        /* Store the found term. */
        cache[cache_size++] = (seq_t)next;
        /* Advance to the next candidate. */
        ++next;
    }
    return cache[n - 1];
}
